// loadedAtStartup records whether the library was open before any test ran. It
// is sampled during package initialization, the only point where "importing
// does not load" is observable.
var loadedAtStartup = Loaded()

// TestImportDoesNotLoad checks that merely importing this package does not open
// the shared library, so the package is importable on machines where the
// library is not installed.
func TestImportDoesNotLoad(t *testing.T) {
	if loadedAtStartup {
		t.Error("library was loaded at import time; loading must be lazy")
	}
}

// TestHasUnknownSymbol checks that probing an absent symbol reports false
// rather than panicking, whether or not the library is present.
func TestHasUnknownSymbol(t *testing.T) {
	if Has("__definitely_not_a_real_symbol") {
		t.Error("Has reported a nonexistent symbol as present")
	}
}

// TestCheckLibSymUnknown checks that reaching a symbol absent from the loaded
// library yields *SymbolError naming the symbol, not a nil-func panic. When the
// library is unavailable the load error surfaces instead, which is also
// fail-closed.
func TestCheckLibSymUnknown(t *testing.T) {
	err := checkLibSym("__definitely_not_a_real_symbol")
	if err == nil {
		t.Fatal("checkLibSym returned nil for a nonexistent symbol")
	}
	if !Loaded() {
		return // library absent: the load error is the expected result
	}
	var symErr *SymbolError
	if !errors.As(err, &symErr) {
		t.Fatalf("checkLibSym error = %v (%T), want *SymbolError", err, err)
	}
	if symErr.Symbol != "__definitely_not_a_real_symbol" {
		t.Errorf("SymbolError.Symbol = %q, want the probed symbol", symErr.Symbol)
	}
}

